cd /testbed && patch -p1 <<'PATCH'
*** Begin Patch
*** Update File: tokio/tests/sync_broadcast.rs
@@
 #[test]
 fn resubscribe_lagged() {
@@
     assert_empty!(rx_resub);
 }
+
+#[test]
+fn resubscribe_closed() {
+    for &capacity in &[1, 4] {
+        for sent in 0..=capacity + 1 {
+            let (tx, rx) = broadcast::channel(capacity);
+            for value in 0..sent {
+                assert_ok!(tx.send(value));
+            }
+            drop(tx);
+
+            let mut rx_try = rx.resubscribe();
+            let mut rx_recv = rx_try.resubscribe();
+            drop(rx);
+
+            assert_closed!(rx_try.try_recv());
+            drop(rx_try);
+
+            let mut recv = task::spawn(rx_recv.recv());
+            assert!(is_closed(assert_ready_err!(recv.poll())));
+        }
+    }
+}
*** End Patch
