cd /testbed && patch -p1 <<'PATCH'
--- a/tokio/src/sync/broadcast.rs
+++ b/tokio/src/sync/broadcast.rs
@@ -669,7 +669,12 @@

     tail.rx_cnt = tail.rx_cnt.checked_add(1).expect("overflow");

-    let next = tail.pos;
+    let next = if tail.closed {
+        // Start at the closure marker rather than waiting for another value.
+        tail.pos.wrapping_sub(1)
+    } else {
+        tail.pos
+    };

     drop(tail);

@@ -897,6 +902,9 @@
     /// **after** it has resubscribed. This will not include elements that are
     /// in the queue of the current receiver. Consider the following example.
     ///
+    /// If the channel is closed, the new receiver will also be closed and will
+    /// not receive any values.
+    ///
     /// # Examples
     ///
     /// ```
PATCH
cargo test --offline --test sync_broadcast --features full > /testbed/target/broadcast-regression.log 2>&1; result=$?; tail -35 /testbed/target/broadcast-regression.log; exit "$result"

